mapper.select:
SELECT DISTINCT rs.id, rs.room_id, rs.service_id, rs.provide_count as `count`, s.name, s.standard, s.warn, s.instructions, s.deleted as valid_flag, rs.create_time FROM bbx_meeting_room_service rs LEFT JOIN bbx_meeting_service s ON rs.service_id = s.id
AND rs.tenant_id =#{tenantId} AND s.tenant_id =#{tenantId}
AND rs.room_id = #{condition.roomId}
AND s.name like concat('%',#{condition.name},'%')
ORDER BY rs.create_time DESC

SELECT DISTINCT rd.id, d.id device_id, d.device_name as deviceName, rd.create_time FROM bbx_meeting_room_device_rel rd LEFT JOIN bbx_ioc_device d ON rd.device_id = d.id
AND rd.tenant_id =#{tenantId} AND d.tenant_id =#{tenantId}
AND rd.room_id = #{condition.roomId}
AND d.device_name like concat('%',#{condition.name},'%')
ORDER BY rd.create_time DESC

SELECT DISTINCT rd.id, d.id device_id, d.device_name as deviceName, d.iot_product_code product_key, d.iot_device_dn iot_device_dn, rd.create_time FROM bbx_meeting_room_device_rel rd LEFT JOIN bbx_ioc_device d ON rd.device_id = d.id
AND rd.tenant_id =#{tenantId} AND d.tenant_id =#{tenantId}
AND rd.room_id = #{condition.roomId}
and d.iot_product_code is not null
ORDER BY rd.create_time DESC,rd.id
